INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9604, 'ចំណុចប្រសព្វនៃកន្លះបន្ទាត់ពុះមុំក្នុងទាំងបីរបស់ត្រីកោណ ហៅថាអ្វី?', 'g8-eb7a79b1fd.svg', '["ផ្ចិតរង្វង់ចារឹកក្រៅ", "អរតូសង់", "ផ្ចិតរង្វង់ចារឹកក្នុងត្រីកោណ (Incenter)", "ទីប្រជុំទម្ងន់"]', 2, NULL, 1, 'mcq', 'កន្លះបន្ទាត់ពុះមុំទាំងបីនៃត្រីកោណប្រសព្វគ្នាត្រង់ផ្ចិតរង្វង់ចារឹកក្នុងត្រីកោណ កំណត់ដោយ \(I\)', 'បន្ទាត់និងអង្កត់ពិសេសជួបគ្នានៅក្នុងត្រីកោណ', 'easy', 1, '8', 'បន្ទាត់និងអង្កត់ពិសេសជួបគ្នានៅក្នុងត្រីកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9605, 'បើ \(G\) ជាទីប្រជុំទម្ងន់នៃត្រីកោណ \(ABC\) ហើយ \(AA''\) ជាមេដ្យានគូសចេញពីកំពូល \(A\) តើផលធៀប \(\dfrac{AG}{AA''}\) ស្មើនឹងប៉ុន្មាន?', NULL, '["\\(\\dfrac{1}{3}\\)", "\\(\\dfrac{2}{3}\\)", "\\(\\dfrac{1}{2}\\)", "\\(\\dfrac{3}{4}\\)"]', 1, NULL, 1, 'mcq', 'ទីប្រជុំទម្ងន់ស្ថិតនៅចម្ងាយ \(\dfrac{2}{3}\) នៃមេដ្យានពីកំពូល ៖ \(AG = \dfrac{2}{3}AA''\)', 'បន្ទាត់និងអង្កត់ពិសេសជួបគ្នានៅក្នុងត្រីកោណ', 'easy', 1, '8', 'បន្ទាត់និងអង្កត់ពិសេសជួបគ្នានៅក្នុងត្រីកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9606, 'បើ \(G\) ជាទីប្រជុំទម្ងន់នៃត្រីកោណ \(ABC\) និង \(AA''\) ជាមេដ្យាន គូសទៅបាត \(BC\) តើ \(\dfrac{GA''}{AA''}\) ស្មើនឹងប៉ុន្មាន?', NULL, '["\\(\\dfrac{1}{3}\\)", "\\(\\dfrac{1}{2}\\)", "\\(\\dfrac{2}{3}\\)", "\\(\\dfrac{1}{4}\\)"]', 0, NULL, 1, 'mcq', '\(GA'' = \dfrac{1}{3}AA''\)', 'បន្ទាត់និងអង្កត់ពិសេសជួបគ្នានៅក្នុងត្រីកោណ', 'easy', 1, '8', 'បន្ទាត់និងអង្កត់ពិសេសជួបគ្នានៅក្នុងត្រីកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9607, 'តើចំណុចប្រសព្វនៃមេដ្យាទ័រទាំងបី (ផ្ចិតរង្វង់ចារឹកក្រៅ \(O\)) មានចម្ងាយស្មើគ្នាទៅនឹងអ្វី?', NULL, '["ជើងកម្ពស់ទាំងបី", "កំពូលទាំងបីនៃត្រីកោណ", "ជើងមេដ្យានទាំងបី", "ជ្រុងទាំងបីនៃត្រីកោណ"]', 1, NULL, 1, 'mcq', 'ផ្ចិតរង្វង់ចារឹកក្រៅ \(O\) មានចម្ងាយស្មើគ្នាទៅកំពូលទាំងបី ៖ \(OA = OB = OC = R\)', 'បន្ទាត់និងអង្កត់ពិសេសជួបគ្នានៅក្នុងត្រីកោណ', 'easy', 1, '8', 'បន្ទាត់និងអង្កត់ពិសេសជួបគ្នានៅក្នុងត្រីកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9608, 'តើចំណុចប្រសព្វនៃកន្លះបន្ទាត់ពុះមុំទាំងបី (ផ្ចិតរង្វង់ចារឹកក្នុង \(I\)) មានចម្ងាយស្មើគ្នាទៅនឹងអ្វី?', NULL, '["មេដ្យានទាំងបី", "កម្ពស់ទាំងបី", "ជ្រុងទាំងបីនៃត្រីកោណ", "កំពូលទាំងបីនៃត្រីកោណ"]', 2, NULL, 1, 'mcq', 'ផ្ចិតរង្វង់ចារឹកក្នុង \(I\) មានចម្ងាយស្មើគ្នាទៅជ្រុងទាំងបីនៃត្រីកោណ ៖ \(d(I, AB) = d(I, BC) = d(I, AC) = r\)', 'បន្ទាត់និងអង្កត់ពិសេសជួបគ្នានៅក្នុងត្រីកោណ', 'easy', 1, '8', 'បន្ទាត់និងអង្កត់ពិសេសជួបគ្នានៅក្នុងត្រីកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9609, 'ក្នុងត្រីកោណសម័ង្ស តើចំណុចពិសេសទាំងបួន (ទីប្រជុំទម្ងន់ \(G\), ផ្ចិតចារឹកក្រៅ \(O\), អរតូសង់ \(H\), ផ្ចិតចារឹកក្នុង \(I\)) មានទំនាក់ទំនងគ្នាយ៉ាងដូចម្តេច?', NULL, '["នៅដាច់ដោយឡែកពីគ្នា", "បង្កើតបានជាត្រីកោណសម័ង្សតូចមួយ", "រត់ត្រង់ជួរគ្នាតែមិនត្រួតគ្នា", "ត្រួតស៊ីគ្នាជាចំណុចតែមួយ"]', 3, NULL, 1, 'mcq', 'ក្នុងត្រីកោណសម័ង្ស បន្ទាត់ពិសេសទាំងបួនត្រួតស៊ីគ្នា នាំឱ្យចំណុច \(G, O, H, I\) ត្រួតស៊ីគ្នាជាចំណុចតែមួយ', 'បន្ទាត់និងអង្កត់ពិសេសជួបគ្នានៅក្នុងត្រីកោណ', 'easy', 1, '8', 'បន្ទាត់និងអង្កត់ពិសេសជួបគ្នានៅក្នុងត្រីកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9610, 'ក្នុងត្រីកោណកែងមួយ តើអរតូសង់ \(H\) ស្ថិតនៅត្រង់ទីតាំងណា?', NULL, '["ត្រង់កំពូលនៃមុំកែង", "នៅខាងក្រៅត្រីកោណ", "នៅចំផ្ចិតរង្វង់ចារឹកក្នុង", "នៅចំកណ្តាលអ៊ីប៉ូតេនុស"]', 0, NULL, 1, 'mcq', 'ក្នុងត្រីកោណកែង ជ្រុងមុំកែងទាំងពីរដើរតួជាកម្ពស់ ដូច្នេះកម្ពស់ទាំងបីកាត់គ្នាត្រង់កំពូលមុំកែង', 'បន្ទាត់និងអង្កត់ពិសេសជួបគ្នានៅក្នុងត្រីកោណ', 'easy', 1, '8', 'បន្ទាត់និងអង្កត់ពិសេសជួបគ្នានៅក្នុងត្រីកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9611, 'ក្នុងត្រីកោណ \(ABC\) មេដ្យាន \(AA'' = 12\ \text{cm}\)។ បើ \(G\) ជាទីប្រជុំទម្ងន់ គណនាប្រវែង \(AG\)។', NULL, '["\\(4\\ \text{cm}\\)", "\\(6\\ \text{cm}\\)", "\\(8\\ \text{cm}\\)", "\\(9\\ \text{cm}\\)"]', 2, NULL, 2, 'mcq', '\(AG = \dfrac{2}{3}AA'' = \dfrac{2}{3} 	imes 12 = 8\ 	ext{cm}\)', 'បន្ទាត់និងអង្កត់ពិសេសជួបគ្នានៅក្នុងត្រីកោណ', 'medium', 1, '8', 'បន្ទាត់និងអង្កត់ពិសេសជួបគ្នានៅក្នុងត្រីកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9612, 'ក្នុងត្រីកោណ \(ABC\) មេដ្យាន \(BB'' = 15\ \text{cm}\)។ បើ \(G\) ជាទីប្រជុំទម្ងន់ គណនា \(GB''\)។', NULL, '["\\(3\\ \\text{cm}\\)", "\\(7.5\\ \\text{cm}\\)", "\\(5\\ \\text{cm}\\)", "\\(10\\ \\text{cm}\\)"]', 2, NULL, 2, 'mcq', '\(GB'' = \dfrac{1}{3}BB'' = \dfrac{1}{3} 	imes 15 = 5\ 	ext{cm}\)', 'បន្ទាត់និងអង្កត់ពិសេសជួបគ្នានៅក្នុងត្រីកោណ', 'medium', 1, '8', 'បន្ទាត់និងអង្កត់ពិសេសជួបគ្នានៅក្នុងត្រីកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9613, 'ក្នុងត្រីកោណមួយ ចម្ងាយពីទីប្រជុំទម្ងន់ \(G\) ទៅជើងមេដ្យាន \(A''\) គឺ \(GA'' = 4\ 	ext{cm}\)។ គណនាប្រវែងមេដ្យាន \(AA''\) សរុប។', NULL, '["\\(6\\ \text{cm}\\)", "\\(16\\ \text{cm}\\)", "\\(12\\ \text{cm}\\)", "\\(8\\ \text{cm}\\)"]', 2, NULL, 2, 'mcq', '\(AA'' = 3 	imes GA'' = 3 \times 4 = 12\ \text{cm}\)', 'បន្ទាត់និងអង្កត់ពិសេសជួបគ្នានៅក្នុងត្រីកោណ', 'medium', 1, '8', 'បន្ទាត់និងអង្កត់ពិសេសជួបគ្នានៅក្នុងត្រីកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9614, 'ក្នុងត្រីកោណមួយ គេដឹងថា \(GA'' = 3.5\ 	ext{cm}\) (\(G\) ជាទីប្រជុំទម្ងន់)។ គណនាប្រវែង \(AG\)។', NULL, '["\\(5.25\\ \\text{cm}\\)", "\\(10.5\\ \\text{cm}\\)", "\\(7\\ \\text{cm}\\)", "\\(3.5\\ \\text{cm}\\)"]', 2, NULL, 2, 'mcq', '\(AG = 2 	imes GA'' = 2 \times 3.5 = 7\ \text{cm}\)', 'បន្ទាត់និងអង្កត់ពិសេសជួបគ្នានៅក្នុងត្រីកោណ', 'medium', 1, '8', 'បន្ទាត់និងអង្កត់ពិសេសជួបគ្នានៅក្នុងត្រីកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9615, 'ត្រីកោណកែងមួយមានអ៊ីប៉ូតេនុសប្រវែង \(16\ 	ext{cm}\)។ គណនាកាំនៃរង្វង់ចារឹកក្រៅ \(R\) នៃត្រីកោណនោះ។', NULL, '["\\(4\\ \text{cm}\\)", "\\(5.33\\ \text{cm}\\)", "\\(16\\ \text{cm}\\)", "\\(8\\ \text{cm}\\)"]', 3, NULL, 2, 'mcq', 'ផ្ចិតរង្វង់ចារឹកក្រៅត្រីកោណកែងជាចំណុចកណ្តាលនៃអ៊ីប៉ូតេនុស ៖ \(R = \dfrac{c}{2} = \dfrac{16}{2} = 8\ 	ext{cm}\)', 'បន្ទាត់និងអង្កត់ពិសេសជួបគ្នានៅក្នុងត្រីកោណ', 'medium', 1, '8', 'បន្ទាត់និងអង្កត់ពិសេសជួបគ្នានៅក្នុងត្រីកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9616, 'ក្នុងត្រីកោណ \(ABC\) កែងត្រង់ \(A\) មាន \(BC = 20\ 	ext{cm}\)។ មេដ្យាន \(AM\) គូសទៅអ៊ីប៉ូតេនុស \(BC\) មានប្រវែងស្មើនឹងប៉ុន្មាន?', NULL, '["\\(15\\ \text{cm}\\)", "\\(20\\ \text{cm}\\)", "\\(5\\ \text{cm}\\)", "\\(10\\ \text{cm}\\)"]', 3, NULL, 2, 'mcq', 'មេដ្យានទៅអ៊ីប៉ូតេនុសនៃត្រីកោណកែងស្មើកន្លះអ៊ីប៉ូតេនុស ៖ \(AM = \dfrac{BC}{2} = 10\ 	ext{cm}\)', 'បន្ទាត់និងអង្កត់ពិសេសជួបគ្នានៅក្នុងត្រីកោណ', 'medium', 1, '8', 'បន្ទាត់និងអង្កត់ពិសេសជួបគ្នានៅក្នុងត្រីកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9617, 'បើត្រីកោណ \(ABC\) មានមេដ្យានពីរ \(BB'' = CC''\) ស្មើគ្នា តើត្រីកោណ \(ABC\) ជាប្រភេទត្រីកោណអ្វី?', NULL, '["ត្រីកោណសម័ង្ស", "ត្រីកោណសមបាតកំពូល A", "ត្រីកោណមិនសមបាត", "ត្រីកោណកែង"]', 1, NULL, 2, 'mcq', 'ត្រីកោណដែលមានមេដ្យានពីរស្មើគ្នា គឺជាត្រីកោណសមបាត', 'បន្ទាត់និងអង្កត់ពិសេសជួបគ្នានៅក្នុងត្រីកោណ', 'medium', 1, '8', 'បន្ទាត់និងអង្កត់ពិសេសជួបគ្នានៅក្នុងត្រីកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9618, 'ក្នុងត្រីកោណទាលមួយ (មានមុំមួយធំជាង \(90^\circ\)) តើអរតូសង់ \(H\) ស្ថិតនៅទីណា?', NULL, '["នៅខាងក្រៅត្រីកោណ", "នៅលើជ្រុងវែងជាងគេ", "ត្រង់កំពូលនៃមុំទាល", "នៅខាងក្នុងត្រីកោណ"]', 0, NULL, 2, 'mcq', 'ក្នុងត្រីកោណទាល កម្ពស់ទាំងបីប្រសព្វគ្នានៅខាងក្រៅត្រីកោណ', 'បន្ទាត់និងអង្កត់ពិសេសជួបគ្នានៅក្នុងត្រីកោណ', 'medium', 1, '8', 'បន្ទាត់និងអង្កត់ពិសេសជួបគ្នានៅក្នុងត្រីកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9619, 'ក្នុងត្រីកោណទាលមួយ តើផ្ចិតរង្វង់ចារឹកក្រៅ \(O\) ស្ថិតនៅទីណា?', NULL, '["នៅខាងក្នុងត្រីកោណ", "ត្រង់កំពូលមុំទាល", "នៅលើជ្រុងឈមមុំទាល", "នៅខាងក្រៅត្រីកោណ"]', 3, NULL, 2, 'mcq', 'ក្នុងត្រីកោណទាល ផ្ចិតរង្វង់ចារឹកក្រៅ \(O\) ស្ថិតនៅខាងក្រៅត្រីកោណ', 'បន្ទាត់និងអង្កត់ពិសេសជួបគ្នានៅក្នុងត្រីកោណ', 'medium', 1, '8', 'បន្ទាត់និងអង្កត់ពិសេសជួបគ្នានៅក្នុងត្រីកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9620, 'សម្រាប់ត្រីកោណគ្រប់ប្រភេទ (ស្រួច កែង ឬទាល) តើផ្ចិតរង្វង់ចារឹកក្នុង \(I\) ស្ថិតនៅទីណាជានិច្ច?', NULL, '["នៅខាងក្រៅត្រីកោណពេលមុំទាល", "នៅខាងក្នុងត្រីកោណជានិច្ច", "អាចនៅក្រៅឬក្នុង", "នៅលើជ្រុងពេលត្រីកោណកែង"]', 1, NULL, 2, 'mcq', 'ផ្ចិតរង្វង់ចារឹកក្នុង \(I\) ជាប្រសព្វបន្ទាត់ពុះមុំក្នុង ដូច្នេះវាស្ថិតនៅខាងក្នុងត្រីកោណជានិច្ច', 'បន្ទាត់និងអង្កត់ពិសេសជួបគ្នានៅក្នុងត្រីកោណ', 'medium', 1, '8', 'បន្ទាត់និងអង្កត់ពិសេសជួបគ្នានៅក្នុងត្រីកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9621, 'ត្រីកោណមួយមានបរិមាត្រ \(P = 36\ 	ext{cm}\) និងកាំរង្វង់ចារឹកក្នុង \(r = 3\ 	ext{cm}\)។ គណនាផ្ទៃក្រឡានៃត្រីកោណនោះ។', NULL, '["\\(36\\ \text{cm}^2\\)", "\\(54\\ \text{cm}^2\\)", "\\(27\\ \text{cm}^2\\)", "\\(108\\ \text{cm}^2\\)"]', 1, NULL, 2, 'mcq', 'កន្លះបរិមាត្រ ៖ \(p = \dfrac{36}{2} = 18\ 	ext{cm} \Rightarrow S = p 	imes r = 18 	imes 3 = 54\ 	ext{cm}^2\)', 'បន្ទាត់និងអង្កត់ពិសេសជួបគ្នានៅក្នុងត្រីកោណ', 'medium', 1, '8', 'បន្ទាត់និងអង្កត់ពិសេសជួបគ្នានៅក្នុងត្រីកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9622, 'ត្រីកោណ \(ABC\) មានផ្ទៃក្រឡា \(48\ 	ext{cm}^2\)។ \(G\) ជាទីប្រជុំទម្ងន់នៃត្រីកោណ។ គណនាផ្ទៃក្រឡានៃត្រីកោណ \(GBC\)។', NULL, '["\\(12\\ \text{cm}^2\\)", "\\(16\\ \text{cm}^2\\)", "\\(24\\ \text{cm}^2\\)", "\\(8\\ \text{cm}^2\\)"]', 1, NULL, 2, 'mcq', 'ទីប្រជុំទម្ងន់ចែកត្រីកោណជា ៣ ត្រីកោណតូចៗដែលមានផ្ទៃស្មើគ្នា ៖ \(S_{GBC} = \dfrac{48}{3} = 16\ 	ext{cm}^2\)', 'បន្ទាត់និងអង្កត់ពិសេសជួបគ្នានៅក្នុងត្រីកោណ', 'medium', 1, '8', 'បន្ទាត់និងអង្កត់ពិសេសជួបគ្នានៅក្នុងត្រីកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9623, 'ក្នុងត្រីកោណសមបាត \(ABC\) (\(AB = AC\)) តើបន្ទាត់ពិសេសណាខ្លះដែលត្រួតស៊ីគ្នាគូសចេញពីកំពូល \(A\)?', NULL, '["មេដ្យាន កម្ពស់ មេដ្យាទ័រ និងកន្លះបន្ទាត់ពុះមុំ", "តែកម្ពស់និងបន្ទាត់ពុះមុំប៉ុណ្ណោះ", "គ្មានបន្ទាត់ណាត្រួតស៊ីគ្នាទេ", "តែមេដ្យាននិងកម្ពស់ប៉ុណ្ណោះ"]', 0, NULL, 2, 'mcq', 'ក្នុងត្រីកោណសមបាត បន្ទាត់ពិសេសទាំង ៤ គូសចេញពីកំពូលត្រួតស៊ីគ្នាជាបន្ទាត់តែមួយ', 'បន្ទាត់និងអង្កត់ពិសេសជួបគ្នានៅក្នុងត្រីកោណ', 'medium', 1, '8', 'បន្ទាត់និងអង្កត់ពិសេសជួបគ្នានៅក្នុងត្រីកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9624, 'ក្នុងត្រីកោណសម័ង្សមួយ បើកាំរង្វង់ចារឹកក្រៅគឺ \(R = 10\ 	ext{cm}\) តើកាំរង្វង់ចារឹកក្នុង \(r\) ស្មើនឹងប៉ុន្មាន?', NULL, '["\\(2.5\\ \text{cm}\\)", "\\(5\\ \text{cm}\\)", "\\(3.33\\ \text{cm}\\)", "\\(10\\ \text{cm}\\)"]', 1, NULL, 2, 'mcq', 'ក្នុងត្រីកោណសម័ង្ស ទីប្រជុំទម្ងន់ជាផ្ចិតចារឹកក្នុងនិងក្រៅ នាំឱ្យ \(r = \dfrac{1}{2}R = 5\ 	ext{cm}\)', 'បន្ទាត់និងអង្កត់ពិសេសជួបគ្នានៅក្នុងត្រីកោណ', 'medium', 1, '8', 'បន្ទាត់និងអង្កត់ពិសេសជួបគ្នានៅក្នុងត្រីកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9625, 'ត្រីកោណសម័ង្សមួយមានរង្វាស់ជ្រុង \(a = 6\sqrt{3}\ 	ext{cm}\)។ គណនាកាំរង្វង់ចារឹកក្រៅ \(R\) នៃត្រីកោណសម័ង្សនោះ។', NULL, '["\\(3\\ \text{cm}\\)", "\\(6\\ \text{cm}\\)", "\\(9\\ \text{cm}\\)", "\\(12\\ \text{cm}\\)"]', 1, NULL, 3, 'mcq', 'កម្ពស់ ៖ \(h = \dfrac{a\sqrt{3}}{2} = \dfrac{6\sqrt{3} 	imes \sqrt{3}}{2} = 9\ 	ext{cm}\) នាំឱ្យ \(R = \dfrac{2}{3}h = 6\ 	ext{cm}\)', 'បន្ទាត់និងអង្កត់ពិសេសជួបគ្នានៅក្នុងត្រីកោណ', 'hard', 1, '8', 'បន្ទាត់និងអង្កត់ពិសេសជួបគ្នានៅក្នុងត្រីកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9626, 'ត្រីកោណកែងមួយមានជ្រុងមុំកែង \(a = 6\ 	ext{cm}, b = 8\ 	ext{cm}\) និងអ៊ីប៉ូតេនុស \(c = 10\ 	ext{cm}\)។ គណនាកាំរង្វង់ចារឹកក្នុង \(r\)។', NULL, '["\\(3\\ \text{cm}\\)", "\\(1\\ \text{cm}\\)", "\\(2\\ \text{cm}\\)", "\\(4\\ \text{cm}\\)"]', 2, NULL, 3, 'mcq', '\(r = \dfrac{a + b - c}{2} = \dfrac{6 + 8 - 10}{2} = \dfrac{4}{2} = 2\ 	ext{cm}\)', 'បន្ទាត់និងអង្កត់ពិសេសជួបគ្នានៅក្នុងត្រីកោណ', 'hard', 1, '8', 'បន្ទាត់និងអង្កត់ពិសេសជួបគ្នានៅក្នុងត្រីកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9627, 'ក្នុងប្លង់កូអរដោនេ ត្រីកោណ \(ABC\) មានកំពូល \(A(2, 4), B(5, 1), C(5, 7)\)។ រកកូអរដោនេនៃទីប្រជុំទម្ងន់ \(G\)។', NULL, '["\\(G(6, 6)\\)", "\\(G(4, 4)\\)", "\\(G(3, 4)\\)", "\\(G(4, 3)\\)"]', 1, NULL, 3, 'mcq', '\(x_G = \dfrac{2 + 5 + 5}{3} = 4\), \(y_G = \dfrac{4 + 1 + 7}{3} = 4 \Rightarrow G(4, 4)\)', 'បន្ទាត់និងអង្កត់ពិសេសជួបគ្នានៅក្នុងត្រីកោណ', 'hard', 1, '8', 'បន្ទាត់និងអង្កត់ពិសេសជួបគ្នានៅក្នុងត្រីកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9628, 'មេដ្យានទាំងបីនៃត្រីកោណ \(ABC\) បែងចែកត្រីកោណធំជា ៦ ត្រីកោណតូចៗ។ បើផ្ទៃត្រីកោណ \(ABC\) ស្មើ \(72\ 	ext{cm}^2\) គណនាផ្ទៃនៃត្រីកោណតូចមួយ។', NULL, '["\\(6\\ \text{cm}^2\\)", "\\(18\\ \text{cm}^2\\)", "\\(12\\ \text{cm}^2\\)", "\\(24\\ \text{cm}^2\\)"]', 2, NULL, 3, 'mcq', 'មេដ្យានទាំងបីចែកត្រីកោណជា ៦ ត្រីកោណតូចៗមានផ្ទៃស្មើគ្នា ៖ \(\dfrac{72}{6} = 12\ 	ext{cm}^2\)', 'បន្ទាត់និងអង្កត់ពិសេសជួបគ្នានៅក្នុងត្រីកោណ', 'hard', 1, '8', 'បន្ទាត់និងអង្កត់ពិសេសជួបគ្នានៅក្នុងត្រីកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9629, 'ក្នុងត្រីកោណមិនសម័ង្សមួយ ចំណុចអរតូសង់ \(H\), ទីប្រជុំទម្ងន់ \(G\) និងផ្ចិតចារឹកក្រៅ \(O\) ស្ថិតនៅលើបន្ទាត់តែមួយ (បន្ទាត់អយល័រ Euler Line)។ តើផលធៀប \(\dfrac{HG}{GO}\) ស្មើនឹងប៉ុន្មាន?', NULL, '["\\(2\\)", "\\(\\dfrac{1}{2}\\)", "\\(1\\)", "\\(3\\)"]', 0, NULL, 3, 'mcq', 'តាមទ្រឹស្តីបទបន្ទាត់អយល័រ ចម្ងាយ \(HG = 2 GO \Rightarrow \dfrac{HG}{GO} = 2\)', 'បន្ទាត់និងអង្កត់ពិសេសជួបគ្នានៅក្នុងត្រីកោណ', 'hard', 1, '8', 'បន្ទាត់និងអង្កត់ពិសេសជួបគ្នានៅក្នុងត្រីកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9630, 'ក្នុងត្រីកោណ \(ABC\) គេដឹងថាមុំ \(ngle A = 70^\circ\)។ \(I\) ជាផ្ចិតរង្វង់ចារឹកក្នុងត្រីកោណ។ គណនារង្វាស់មុំ \(ngle BIC\)។', NULL, '["\\(110^\\circ\\)", "\\(140^\\circ\\)", "\\(135^\\circ\\)", "\\(125^\\circ\\)"]', 3, NULL, 3, 'mcq', '\(ngle BIC = 90^\circ + \dfrac{ngle A}{2} = 90^\circ + 35^\circ = 125^\circ\)', 'បន្ទាត់និងអង្កត់ពិសេសជួបគ្នានៅក្នុងត្រីកោណ', 'hard', 1, '8', 'បន្ទាត់និងអង្កត់ពិសេសជួបគ្នានៅក្នុងត្រីកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9631, 'ក្នុងត្រីកោណស្រួច \(ABC\) មានមុំ \(ngle A = 50^\circ\)។ \(H\) ជាអរតូសង់នៃត្រីកោណ។ គណនារង្វាស់មុំ \(ngle BHC\)។', NULL, '["\\(130^\\circ\\)", "\\(140^\\circ\\)", "\\(115^\\circ\\)", "\\(100^\\circ\\)"]', 0, NULL, 3, 'mcq', '\(ngle BHC = 180^\circ - ngle A = 180^\circ - 50^\circ = 130^\circ\)', 'បន្ទាត់និងអង្កត់ពិសេសជួបគ្នានៅក្នុងត្រីកោណ', 'hard', 1, '8', 'បន្ទាត់និងអង្កត់ពិសេសជួបគ្នានៅក្នុងត្រីកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9632, 'សួនផ្ការាងត្រីកោណមួយមានកំពូលបីជាទីតាំងដើមឈើធំ \(A, B, C\)។ គេចង់ដាក់បង្គោលភ្លើងបំភ្លឺមួយដើមឱ្យមានចម្ងាយស្មើគ្នាទៅកាន់ដើមឈើទាំងបី។ តើគេត្រូវកំណត់ទីតាំងបង្គោលភ្លើងត្រង់ចំណុចប្រសព្វនៃបន្ទាត់អ្វី?', NULL, '["មេដ្យាទ័រនៃជ្រុងទាំងបី (ផ្ចិតរង្វង់ចារឹកក្រៅ O)", "មេដ្យាននៃជ្រុងទាំងបី", "កម្ពស់នៃជ្រុងទាំងបី", "កន្លះបន្ទាត់ពុះមុំ"]', 0, NULL, 3, 'mcq', 'ចំណុចដែលមានចម្ងាយស្មើគ្នាទៅកំពូលទាំងបី គឺជាផ្ចិតនៃរង្វង់ចារឹកក្រៅត្រីកោណ (ប្រសព្វមេដ្យាទ័រ)', 'បន្ទាត់និងអង្កត់ពិសេសជួបគ្នានៅក្នុងត្រីកោណ', 'pisa', 1, '8', 'បន្ទាត់និងអង្កត់ពិសេសជួបគ្នានៅក្នុងត្រីកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9633, 'ទីប្រជុំជនមួយមានផ្លូវធំ ៣ ខ្វែងគ្នាបង្កើតបានជារាងត្រីកោណ។ អាជីវករម្នាក់ចង់បើកតូបលក់ទំនិញនៅទីតាំងមួយដែលនៅស្មើចម្ងាយពីផ្លូវទាំងបី។ តើគាត់ត្រូវជ្រើសរើសចំណុចប្រសព្វនៃបន្ទាត់ណា?', NULL, '["មេដ្យានទាំងបី", "កម្ពស់ទាំងបី", "មេដ្យាទ័រនៃជ្រុងទាំងបី", "កន្លះបន្ទាត់ពុះមុំក្នុងទាំងបី (ផ្ចិតរង្វង់ចារឹកក្នុង I)"]', 3, NULL, 3, 'mcq', 'ចំណុចដែលនៅស្មើចម្ងាយពីជ្រុង (ផ្លូវ) ទាំងបី គឺជាផ្ចិតរង្វង់ចារឹកក្នុង (ប្រសព្វបន្ទាត់ពុះមុំ)', 'បន្ទាត់និងអង្កត់ពិសេសជួបគ្នានៅក្នុងត្រីកោណ', 'pisa', 1, '8', 'បន្ទាត់និងអង្កត់ពិសេសជួបគ្នានៅក្នុងត្រីកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9634, 'ជាងដែកម្នាក់ចង់ទប់ផ្លាកសញ្ញាផ្សាយពាណិជ្ជកម្មរាងត្រីកោណមួយផ្ទាំងឱ្យមានលំនឹងផ្ដេកដោយប្រើទ្រនាប់ចុងម្ជុលតែមួយគត់។ តើគាត់ត្រូវដាក់ទ្រនាប់ចំចំណុចណា?', NULL, '["ផ្ចិតរង្វង់ចារឹកក្នុង I", "ទីប្រជុំទម្ងន់ G (Centroid)", "ផ្ចិតរង្វង់ចារឹកក្រៅ O", "អរតូសង់ H"]', 1, NULL, 3, 'mcq', 'ទីប្រជុំទម្ងន់ គឺជាចំណុចកណ្តាលទំនាញ (Center of Gravity) ដែលអាចទប់វត្ថុរាងត្រីកោណឱ្យមានលំនឹង', 'បន្ទាត់និងអង្កត់ពិសេសជួបគ្នានៅក្នុងត្រីកោណ', 'pisa', 1, '8', 'បន្ទាត់និងអង្កត់ពិសេសជួបគ្នានៅក្នុងត្រីកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9635, 'ភូមិបី \(A, B, C\) បង្កើតបានជាត្រីកោណកែងត្រង់ \(A\) ដែល \(AB = 6\ 	ext{km}\) និង \(AC = 8\ 	ext{km}\)។ ក្រុមហ៊ុនទូរស័ព្ទចង់ដាក់អង់តែនមួយនៅស្មើចម្ងាយពីភូមិទាំងបី។ តើចម្ងាយពីអង់តែនទៅភូមិនីមួយៗស្មើប៉ុន្មាន?', NULL, '["\\(10\\ \text{km}\\)", "\\(4.8\\ \text{km}\\)", "\\(5\\ \text{km}\\)", "\\(7\\ \text{km}\\)"]', 2, NULL, 3, 'mcq', 'អ៊ីប៉ូតេនុស ៖ \(BC = 10\ 	ext{km}\)។ អង់តែននៅចំកណ្តាល \(BC\) នាំឱ្យ \(R = \dfrac{10}{2} = 5\ 	ext{km}\)', 'បន្ទាត់និងអង្កត់ពិសេសជួបគ្នានៅក្នុងត្រីកោណ', 'pisa', 1, '8', 'បន្ទាត់និងអង្កត់ពិសេសជួបគ្នានៅក្នុងត្រីកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9636, 'ក្រុងបីបង្កើតបានជាត្រីកោណសម័ង្សដែលមានជ្រុង \(12\ 	ext{km}\)។ គេចង់សាងសង់ស្ថានីយពន្លត់អគ្គិភ័យកណ្តាលមួយដែលស្មើចម្ងាយពីក្រុងទាំងបី។ គណនាចម្ងាយពីស្ថានីយទៅកាន់ក្រុងនីមួយៗ (យក \(\sqrt{3} pprox 1.732\))។', NULL, '["\\(3.46\\ \text{km}\\)", "\\(10.39\\ \text{km}\\)", "\\(6\\ \text{km}\\)", "\\(6.93\\ \text{km}\\)"]', 3, NULL, 3, 'mcq', '\(h = \dfrac{12\sqrt{3}}{2} = 6\sqrt{3}\ 	ext{km} \Rightarrow R = \dfrac{2}{3}(6\sqrt{3}) = 4\sqrt{3} pprox 4 	imes 1.732 = 6.93\ 	ext{km}\)', 'បន្ទាត់និងអង្កត់ពិសេសជួបគ្នានៅក្នុងត្រីកោណ', 'pisa', 1, '8', 'បន្ទាត់និងអង្កត់ពិសេសជួបគ្នានៅក្នុងត្រីកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9637, 'ក្នុងត្រីកោណ \(ABC\) មេដ្យាន \(AA'' = 18\ 	ext{cm}\)។ \(G\) ជាទីប្រជុំទម្ងន់នៃត្រីកោណ។
ក. សរសេររូបមន្តទំនាក់ទំនងរវាង \(AG\) និង \(AA''\)។
ខ. គណនាប្រវែង \(AG\)។
គ. គណនាប្រវែង \(GA''\)។', 'g8-dcefc26d80.svg', '[]', 0, NULL, 5, 'writing', 'ក. ទំនាក់ទំនងទីប្រជុំទម្ងន់ ៖ \(AG = \dfrac{2}{3}AA''\) និង \(GA'' = \dfrac{1}{3}AA''\) (2 ពិន្ទុ)
ខ. គណនា \(AG = \dfrac{2}{3} 	imes 18 = 12\ 	ext{cm}\) (2 ពិន្ទុ)
គ. គណនា \(GA'' = 18 - 12 = 6\ 	ext{cm}\) (1 ពិន្ទុ)', 'បន្ទាត់និងអង្កត់ពិសេសជួបគ្នានៅក្នុងត្រីកោណ', 'easy', 0, '8', 'បន្ទាត់និងអង្កត់ពិសេសជួបគ្នានៅក្នុងត្រីកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9638, 'គេឱ្យត្រីកោណ \(ABC\) ដែលមានមេដ្យាន \(BB''\) និង \(CC''\) មានប្រវែងស្មើគ្នា (\(BB'' = CC''\)) កាត់គ្នាត្រង់ \(G\)។
ក. បង្ហាញថា \(GB = GC\) និង \(GB'' = GC''\)។
ខ. បង្ហាញថាទីប្រជុំទម្ងន់ \(G\) ស្ថិតនៅលើមេដ្យាទ័រនៃអង្កត់ \(BC\)។
គ. ទាញបញ្ជាក់ថាត្រីកោណ \(ABC\) ជាត្រីកោណសមបាតកំពូល \(A\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(GB = \dfrac{2}{3}BB''\) និង \(GC = \dfrac{2}{3}CC''\)។ ដោយ \(BB'' = CC'' \Rightarrow GB = GC\) និង \(GB'' = GC'' = \dfrac{1}{3}BB''\) (2 ពិន្ទុ)
ខ. ដោយ \(GB = GC\) នាំឱ្យចំណុច \(G\) ស្មើចម្ងាយពី \(B\) និង \(C\) ដូចនេះ \(G\) ស្ថិតនៅលើមេដ្យាទ័រនៃ \(BC\) (1 ពិន្ទុ)
គ. មេដ្យាន \(AA''\) កាត់តាម \(G\) និង \(A''\) (ចំណុចកណ្តាល \(BC\)) នាំឱ្យ \(AA''\) ជាមេដ្យាទ័រនៃ \(BC\) នាំឱ្យ \(AB = AC\) (សមបាតកំពូល \(A\)) (2 ពិន្ទុ)', 'បន្ទាត់និងអង្កត់ពិសេសជួបគ្នានៅក្នុងត្រីកោណ', 'medium', 0, '8', 'បន្ទាត់និងអង្កត់ពិសេសជួបគ្នានៅក្នុងត្រីកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9639, 'ត្រីកោណ \(ABC\) កែងត្រង់ \(A\) មាន \(AB = 12\ \text{cm}\) និង \(AC = 16\ \text{cm}\)។ \(M\) ជាចំណុចកណ្តាលនៃអ៊ីប៉ូតេនុស \(BC\)។
ក. គណនាប្រវែងអ៊ីប៉ូតេនុស \(BC\)។
ខ. បង្ហាញថា \(M\) ជាផ្ចិតនៃរង្វង់ចារឹកក្រៅត្រីកោណ \(ABC\)។
គ. គណនាប្រវែងមេដ្យាន \(AM\) និងកាំរង្វង់ចារឹកក្រៅ \(R\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. តាមពីតាក័រ ៖ \(BC = \sqrt{12^2 + 16^2} = \sqrt{144 + 256} = \sqrt{400} = 20\ \text{cm}\) (2 ពិន្ទុ)
ខ. ក្នុងត្រីកោណកែង ចំណុចកណ្តាលនៃអ៊ីប៉ូតេនុសស្មើចម្ងាយពីកំពូលទាំងបី (\(MA = MB = MC\)) ដូច្នេះ \(M\) ជាផ្ចិតរង្វង់ចារឹកក្រៅ (1 ពិន្ទុ)
គ. \(AM = \dfrac{BC}{2} = 10\ \text{cm}\) និងកាំ \(R = 10\ \text{cm}\) (2 ពិន្ទុ)', 'បន្ទាត់និងអង្កត់ពិសេសជួបគ្នានៅក្នុងត្រីកោណ', 'medium', 0, '8', 'បន្ទាត់និងអង្កត់ពិសេសជួបគ្នានៅក្នុងត្រីកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9640, 'ត្រីកោណ \(ABC\) មួយមានរង្វាស់ជ្រុង \(a = 13\ \text{cm}, b = 14\ \text{cm}, c = 15\ \text{cm}\) និងមានផ្ទៃក្រឡា \(S = 84\ \text{cm}^2\)។
ក. គណនាបរិមាត្រ \(P\) និងកន្លះបរិមាត្រ \(p\) នៃត្រីកោណនោះ។
ខ. សរសេររូបមន្តទំនាក់ទំនងរវាងផ្ទៃក្រឡា កន្លះបរិមាត្រ និងកាំរង្វង់ចារឹកក្នុង \(r\)។
គ. គណនាកាំរង្វង់ចារឹកក្នុង \(r\) នៃត្រីកោណ។', 'g8-eb7a79b1fd.svg', '[]', 0, NULL, 5, 'writing', 'ក. បរិមាត្រ ៖ \(P = 13 + 14 + 15 = 42\ \text{cm}\); កន្លះបរិមាត្រ ៖ \(p = \dfrac{42}{2} = 21\ \text{cm}\) (2 ពិន្ទុ)
ខ. រូបមន្តទំនាក់ទំនង ៖ \(S = p \times r\) (1 ពិន្ទុ)
គ. ទាញបានកាំ ៖ \(r = \dfrac{S}{p} = \dfrac{84}{21} = 4\ \text{cm}\) (2 ពិន្ទុ)', 'បន្ទាត់និងអង្កត់ពិសេសជួបគ្នានៅក្នុងត្រីកោណ', 'medium', 0, '8', 'បន្ទាត់និងអង្កត់ពិសេសជួបគ្នានៅក្នុងត្រីកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9641, 'គេឱ្យអង្កត់បាត \(AB = 8\ \text{cm}\) និងទីប្រជុំទម្ងន់ \(G\) ដែលដឹងថាចម្ងាយពី \(G\) ទៅចំណុចកណ្តាល \(M\) នៃ \(AB\) គឺ \(GM = 3\ \text{cm}\)។
ក. ពន្យល់ពីទីតាំងនៃកំពូល \(C\) ធៀបនឹងកន្លះបន្ទាត់ \(MG\)។
ខ. គណនាប្រវែង \(GC\) និងប្រវែងមេដ្យាន \(MC\) សរុប។
គ. រៀបរាប់ជំហានសង់កំពូល \(C\) នៃត្រីកោណ \(ABC\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. កំពូល \(C\) ស្ថិតនៅលើកន្លះបន្ទាត់ \(MG\) បន្តពី \(G\) ព្រោះ \(MC\) ជាមេដ្យានទីបី (1 ពិន្ទុ)
ខ. តាមលក្ខណៈទីប្រជុំទម្ងន់ ៖ \(GC = 2GM = 2 \times 3 = 6\ \text{cm}\) នាំឱ្យ \(MC = GM + GC = 3 + 6 = 9\ \text{cm}\) (2 ពិន្ទុ)
គ. ជំហានសង់ ៖ ១. កំណត់ចំណុចកណ្តាល \(M\) នៃ \(AB\); ២. គូសកន្លះបន្ទាត់ \(MG\); ៣. វាស់ \(GC = 6\ \text{cm}\) នៅលើកន្លះបន្ទាត់នោះ រួចភ្ជាប់ \(CA, CB\) (2 ពិន្ទុ)', 'បន្ទាត់និងអង្កត់ពិសេសជួបគ្នានៅក្នុងត្រីកោណ', 'medium', 0, '8', 'បន្ទាត់និងអង្កត់ពិសេសជួបគ្នានៅក្នុងត្រីកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9642, 'ត្រីកោណសម័ង្ស \(ABC\) មួយមានរង្វាស់ជ្រុង \(a = 12\ \text{cm}\)។
ក. គណនាកម្ពស់ \(h\) នៃត្រីកោណសម័ង្សជាទម្រង់រ៉ាឌីកាល់សម្រួល។
ខ. ពន្យល់ហេតុអ្វីបានជាចំណុច \(G, O, H, I\) ត្រួតស៊ីគ្នា។
គ. គណនាកាំរង្វង់ចារឹកក្រៅ \(R\) និងកាំរង្វង់ចារឹកក្នុង \(r\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(h = \dfrac{a\sqrt{3}}{2} = \dfrac{12\sqrt{3}}{2} = 6\sqrt{3}\ \text{cm}\) (1 ពិន្ទុ)
ខ. ក្នុងត្រីកោណសម័ង្ស មេដ្យាន កម្ពស់ មេដ្យាទ័រ និងកន្លះបន្ទាត់ពុះមុំត្រួតស៊ីគ្នា នាំឱ្យប្រសព្វទាំងបួន \(G, O, H, I\) ត្រួតស៊ីគ្នាជាចំណុចតែមួយ (2 ពិន្ទុ)
គ. \(R = \dfrac{2}{3}h = \dfrac{2}{3}(6\sqrt{3}) = 4\sqrt{3}\ \text{cm}\) និង \(r = \dfrac{1}{3}h = 2\sqrt{3}\ \text{cm}\) (2 ពិន្ទុ)', 'បន្ទាត់និងអង្កត់ពិសេសជួបគ្នានៅក្នុងត្រីកោណ', 'hard', 0, '8', 'បន្ទាត់និងអង្កត់ពិសេសជួបគ្នានៅក្នុងត្រីកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9643, 'គេឱ្យត្រីកោណ \(ABC\) ដែលមាន \(G\) ជាទីប្រជុំទម្ងន់ និង \(A''\) ជាចំណុចកណ្តាលនៃ \(BC\)។
ក. បង្ហាញថា \(\mathcal{A}_{\Delta ABA''} = \mathcal{A}_{\Delta ACA''} = \dfrac{1}{2}\mathcal{A}_{\Delta ABC}\)។
ខ. បង្ហាញថា \(\mathcal{A}_{\Delta GBA''} = \mathcal{A}_{\Delta GCA''}\)។
គ. ទាញបង្ហាញថា \(\mathcal{A}_{\Delta GAB} = \mathcal{A}_{\Delta GBC} = \mathcal{A}_{\Delta GCA} = \dfrac{1}{3}\mathcal{A}_{\Delta ABC}\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. ត្រីកោណ \(ABA''\) និង \(ACA''\) មានកម្ពស់រួមពី \(A\) និងបាតស្មើគ្នា \(BA'' = A''C\) នាំឱ្យផ្ទៃស្មើគ្នា (2 ពិន្ទុ)
ខ. ត្រីកោណ \(GBA''\) និង \(GCA''\) មានកម្ពស់រួមពី \(G\) និងបាត \(BA'' = A''C\) នាំឱ្យផ្ទៃស្មើគ្នា (1 ពិន្ទុ)
គ. ដកសមីការ ៖ \(\mathcal{A}_{GAB} = \mathcal{A}_{ABA''} - \mathcal{A}_{GBA''}\) ដូចគ្នាចំពោះផ្នែកផ្សេងទៀត នាំឱ្យផ្ទៃទាំងបីស្មើគ្នា និងស្មើ \(\dfrac{1}{3}\mathcal{A}_{ABC}\) (2 ពិន្ទុ)', 'បន្ទាត់និងអង្កត់ពិសេសជួបគ្នានៅក្នុងត្រីកោណ', 'hard', 0, '8', 'បន្ទាត់និងអង្កត់ពិសេសជួបគ្នានៅក្នុងត្រីកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9644, 'គេឱ្យត្រីកោណ \(ABC\) ដែលមានមុំ \(ngle A = 120^\circ\) (ត្រីកោណទាល)។ កម្ពស់គូសចេញពី \(B\) គឺ \(BE \perp AC\) (បន្លាយ \(AC\)) និងកម្ពស់ពី \(C\) គឺ \(CF \perp AB\) (បន្លាយ \(AB\)) ប្រសព្វគ្នាត្រង់ \(H\)។
ក. ពន្យល់ហេតុអ្វីបានជាជើងកម្ពស់ \(E\) និង \(F\) ធ្លាក់នៅក្រៅជ្រុងនៃត្រីកោណ។
ខ. គណនាមុំ \(ngle EAF\)។
គ. គណនាមុំ \(ngle BHC\) នៃអរតូសង់។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. មុំ \(ngle A = 120^\circ > 90^\circ\) នាំឱ្យកម្ពស់គូសពី \(B\) និង \(C\) ត្រូវធ្លាក់លើបន្ទាត់បន្លាយនៃជ្រុងឈម (នៅក្រៅត្រីកោណ) (2 ពិន្ទុ)
ខ. មុំ \(ngle EAF\) និងមុំ \(ngle BAC\) ជាមុំទល់កំពូល នាំឱ្យ \(ngle EAF = 120^\circ\) (1 ពិន្ទុ)
គ. ក្នុងចតុកោណ \(AFHE\) មានមុំកែងពីរត្រង់ \(E\) និង \(F\) នាំឱ្យ \(ngle BHC = 180^\circ - 120^\circ = 60^\circ\) (2 ពិន្ទុ)', 'បន្ទាត់និងអង្កត់ពិសេសជួបគ្នានៅក្នុងត្រីកោណ', 'hard', 0, '8', 'បន្ទាត់និងអង្កត់ពិសេសជួបគ្នានៅក្នុងត្រីកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9645, 'ត្រីកោណ \(ABC\) កែងត្រង់ \(A\) មានជ្រុងមុំកែង \(AB = 5\ 	ext{cm}\) និង \(AC = 12\ 	ext{cm}\)។
ក. គណនាប្រវែងអ៊ីប៉ូតេនុស \(BC\) និងផ្ទៃក្រឡា \(S\)។
ខ. គណនាកាំរង្វង់ចារឹកក្រៅ \(R\)។
គ. គណនាកាំរង្វង់ចារឹកក្នុង \(r\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(BC = \sqrt{5^2 + 12^2} = 13\ 	ext{cm}\); ផ្ទៃក្រឡា ៖ \(S = \dfrac{5 	imes 12}{2} = 30\ 	ext{cm}^2\) (2 ពិន្ទុ)
ខ. កាំរង្វង់ចារឹកក្រៅ ៖ \(R = \dfrac{BC}{2} = \dfrac{13}{2} = 6.5\ 	ext{cm}\) (1 ពិន្ទុ)
គ. កន្លះបរិមាត្រ \(p = \dfrac{5 + 12 + 13}{2} = 15\ 	ext{cm} \Rightarrow r = \dfrac{S}{p} = \dfrac{30}{15} = 2\ 	ext{cm}\) (2 ពិន្ទុ)', 'បន្ទាត់និងអង្កត់ពិសេសជួបគ្នានៅក្នុងត្រីកោណ', 'hard', 0, '8', 'បន្ទាត់និងអង្កត់ពិសេសជួបគ្នានៅក្នុងត្រីកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9646, 'សួនសាធារណៈមួយមានរាងជាត្រីកោណ \(ABC\) ដែលមានជ្រុង \(AB = 30\ 	ext{m}, BC = 40\ 	ext{m}, AC = 50\ 	ext{m}\)។ គណៈកម្មការសួនចង់ដំឡើងបង្គោលភ្លើងហ្វាបំភ្លឺមួយដើមឱ្យស្មើចម្ងាយពីកំពូលសួនទាំងបី។
ក. បង្ហាញថាត្រីកោណ \(ABC\) ជាត្រីកោណកែង។
ខ. កំណត់ទីតាំងពិតប្រាកដដែលត្រូវដំឡើងបង្គោលភ្លើង។
គ. គណនាចម្ងាយពីបង្គោលភ្លើងទៅកាន់កំពូលសួននីមួយៗ។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(30^2 + 40^2 = 900 + 1\,600 = 2\,500 = 50^2\) តាមទ្រឹស្តីបទច្រាសពីតាក័រ ត្រីកោណ \(ABC\) កែងត្រង់ \(B\) (2 ពិន្ទុ)
ខ. បង្គោលភ្លើងត្រូវនៅស្មើចម្ងាយពីកំពូលទាំងបី ដូច្នេះវាជាផ្ចិតចារឹកក្រៅ ដែលស្ថិតនៅចំចំណុចកណ្តាលនៃអ៊ីប៉ូតេនុស \(AC\) (2 ពិន្ទុ)
គ. ចម្ងាយទៅកំពូលនីមួយៗគឺ \(R = \dfrac{50}{2} = 25\ 	ext{m}\) (1 ពិន្ទុ)', 'បន្ទាត់និងអង្កត់ពិសេសជួបគ្នានៅក្នុងត្រីកោណ', 'pisa', 0, '8', 'បន្ទាត់និងអង្កត់ពិសេសជួបគ្នានៅក្នុងត្រីកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9647, 'មន្ទីរសុខាភិបាលចង់សាងសង់មន្ទីរពេទ្យបង្អែកថ្មីមួយនៅទីតាំងមួយដែលនៅស្មើចម្ងាយពីផ្លូវជាតិទាំងបីដែលព័ទ្ធជុំវិញស្រុក (ផ្លូវទាំងបីខ្វែងគ្នាជារាងត្រីកោណ)។
ក. តើទីតាំងមន្ទីរពេទ្យត្រូវជាចំណុចពិសេសណា ក្នុងចំណោមចំណុច \(G, O, H, I\)? ពន្យល់។
ខ. បើផ្ទៃដីត្រីកោណនោះមានទំហំ \(60\ 	ext{km}^2\) និងផលបូកប្រវែងផ្លូវទាំងបីគឺ \(30\ 	ext{km}\) គណនាចម្ងាយកែងពីមន្ទីរពេទ្យទៅកាន់ផ្លូវនីមួយៗ។
គ. ហេតុអ្វីបានជាការជ្រើសរើសចំណុចនេះមានសារៈសំខាន់សម្រាប់រថយន្តសង្គ្រោះបន្ទាន់?', NULL, '[]', 0, NULL, 5, 'writing', 'ក. ត្រូវជាចំណុច \(I\) (ផ្ចិតរង្វង់ចារឹកក្នុង) ព្រោះចំណុចនេះនៅស្មើចម្ងាយពីជ្រុង (ផ្លូវ) ទាំងបីនៃត្រីកោណ (2 ពិន្ទុ)
ខ. កន្លះបរិមាត្រ \(p = \dfrac{30}{2} = 15\ 	ext{km}\)។ ចម្ងាយកែងទៅផ្លូវនីមួយៗគឺ \(r = \dfrac{S}{p} = \dfrac{60}{15} = 4\ 	ext{km}\) (2 ពិន្ទុ)
គ. ធានាថារថយន្តសង្គ្រោះបន្ទាន់អាចចេញទៅកាន់ផ្លូវជាតិទាំងបីដោយប្រើចម្ងាយជិតបំផុតស្មើៗគ្នា (ត្រឹម \(4\ 	ext{km}\)) (1 ពិន្ទុ)', 'បន្ទាត់និងអង្កត់ពិសេសជួបគ្នានៅក្នុងត្រីកោណ', 'pisa', 0, '8', 'បន្ទាត់និងអង្កត់ពិសេសជួបគ្នានៅក្នុងត្រីកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9648, 'វិស្វករម្នាក់រចនាផ្លាកសញ្ញាចរាចរណ៍រាងត្រីកោណសម័ង្សមួយផ្ទាំងមានជ្រុង \(60\ 	ext{cm}\)។ គាត់ត្រូវភ្ជាប់បង្គោលទប់នៅចំចំណុចកណ្តាលទំនាញ (ទីប្រជុំទម្ងន់ \(G\))។
ក. គណនាកម្ពស់ \(h\) នៃផ្លាកសញ្ញា (យក \(\sqrt{3} pprox 1.732\))។
ខ. គណនាចម្ងាយពីចំណុចភ្ជាប់បង្គោល \(G\) ទៅកាន់បាតខាងក្រោមនៃផ្លាកសញ្ញា។
គ. គណនាចម្ងាយពីចំណុច \(G\) ទៅកាន់កំពូលខាងលើនៃផ្លាកសញ្ញា។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. កម្ពស់ ៖ \(h = \dfrac{60\sqrt{3}}{2} = 30\sqrt{3} pprox 30 	imes 1.732 = 51.96\ 	ext{cm}\) (2 ពិន្ទុ)
ខ. ចម្ងាយទៅបាត ៖ \(GA'' = \dfrac{1}{3}h = \dfrac{51.96}{3} = 17.32\ 	ext{cm}\) (1 ពិន្ទុ)
គ. ចម្ងាយទៅកំពូល ៖ \(AG = \dfrac{2}{3}h = 2 \times 17.32 = 34.64\ \text{cm}\) (2 ពិន្ទុ)', 'បន្ទាត់និងអង្កត់ពិសេសជួបគ្នានៅក្នុងត្រីកោណ', 'pisa', 0, '8', 'បន្ទាត់និងអង្កត់ពិសេសជួបគ្នានៅក្នុងត្រីកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9649, 'អនុស្ថានីយអគ្គិសនីចំនួន ៣ ស្ថិតនៅទីតាំង \(A, B, C\)។ គេចង់សង់មជ្ឈមណ្ឌលចែកចាយថាមពលមេ \(O\) មួយដែលស្មើចម្ងាយពីអនុស្ថានីយទាំងបី។ ដឹងថា \(AB = AC = 10\ \text{km}\) និង \(BC = 12\ \text{km}\)។
ក. គណនាកម្ពស់ \(AH\) នៃត្រីកោណសមបាត \(ABC\)។
ខ. គណនាផ្ទៃក្រឡានៃត្រីកោណ \(ABC\)។
គ. គណនាចម្ងាយខ្សែបណ្តាញពីមជ្ឈមណ្ឌល \(O\) ទៅកាន់អនុស្ថានីយនីមួយៗ (\(R = \dfrac{abc}{4S}\))។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(BH = 6\ \text{km} \Rightarrow AH = \sqrt{10^2 - 6^2} = 8\ \text{km}\) (2 ពិន្ទុ)
ខ. ផ្ទៃក្រឡា ៖ \(S = \dfrac{12 \times 8}{2} = 48\ \text{km}^2\) (1 ពិន្ទុ)
គ. ចម្ងាយខ្សែបណ្តាញ ៖ \(R = \dfrac{10 \times 10 \times 12}{4 \times 48} = \dfrac{1\,200}{192} = 6.25\ \text{km}\) (2 ពិន្ទុ)', 'បន្ទាត់និងអង្កត់ពិសេសជួបគ្នានៅក្នុងត្រីកោណ', 'pisa', 0, '8', 'បន្ទាត់និងអង្កត់ពិសេសជួបគ្នានៅក្នុងត្រីកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9650, 'មូលដ្ឋានយោធាបី \(A, B, C\) បង្កើតបានជាត្រីកោណមួយ។ ឧទ្ធម្ភាគចក្រមួយគ្រឿងចង់ចុះចតនៅចំណុចមួយក្នុងតំបន់ត្រីកោណ ដែលចំណុចនោះបង្កើតបានជា ៣ តំបន់ស្មើផ្ទៃគ្នាសម្រាប់កងកម្លាំងនីមួយៗទទួលខុសត្រូវ។
ក. តើចំណុចចុះចតនោះត្រូវជាចំណុចពិសេសណា ក្នុងចំណោម \(G, O, H, I\)?
ខ. ពន្យល់មូលហេតុធរណីមាត្រដែលធ្វើឱ្យផ្ទៃទាំងបីស្មើគ្នា។
គ. បើផ្ទៃដីរួមគឺ \(90\ \text{km}^2\) គណនាផ្ទៃដីនៃតំបន់នីមួយៗ។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. ចំណុចចុះចតត្រូវជា ទីប្រជុំទម្ងន់ \(G\) (Centroid) (1 ពិន្ទុ)
ខ. មេដ្យានទាំងបីចែកត្រីកោណជា ៦ ត្រីកោណតូចៗមានផ្ទៃស្មើគ្នា នាំឱ្យត្រីកោណ \(GAB, GBC, GCA\) នីមួយៗផ្សំដោយ ២ ត្រីកោណតូច ដូច្នេះផ្ទៃទាំងបីស្មើគ្នា (2 ពិន្ទុ)
គ. ផ្ទៃដីតំបន់នីមួយៗ ៖ \(\dfrac{90}{3} = 30\ \text{km}^2\) (2 ពិន្ទុ)', 'បន្ទាត់និងអង្កត់ពិសេសជួបគ្នានៅក្នុងត្រីកោណ', 'pisa', 0, '8', 'បន្ទាត់និងអង្កត់ពិសេសជួបគ្នានៅក្នុងត្រីកោណ', NULL, 0);
